import logging
import threading
from taf.internal.managedobject import ManagedObject


class SshReverseForwarding(ManagedObject):

    def __init__(self, ssh_connection, **kwargs):
        super(SshReverseForwarding, self).__init__(**kwargs)

        self._ssh_connection = ssh_connection
        self.add_prerequisite(self._ssh_connection)

        self._forward_port = None
        self._data_exchange = None

        self._transport = None
        self._listen_thread = None
        self._forwarding_port = None

    def config(self, forwarding_port, data_exchange):
        self._forwarding_port = forwarding_port
        self._data_exchange = data_exchange

    def _setup(self):
        self._listen_thread = threading.Thread(target=self._create_reverse_forward_tunnel_and_listen)
        self._listen_thread.setDaemon(True)
        self._listen_thread.start()
        logging.debug("setup ssh reverse forwarding successfully")

    def _create_reverse_forward_tunnel_and_listen(self):
        self._transport = self._ssh_connection.request_port_forward_and_return_transport(self._forwarding_port)
        while True:
            chan = self._transport.accept(1000)
            if not chan:
                continue
            thr = threading.Thread(target=self._data_exchange.forwarding_handler, args=(chan,))
            thr.setDaemon(True)
            thr.start()

    def _teardown(self):
        logging.debug("{} teardown ssh reverse forwarding".format(self._ssh_connection.address))
